        detail.loadHTMLString(articleHTML(title:remaining==0 ? "All caught up.":"Unread articles",source:"YOUR READING",notice:remaining==0 ? "No unread articles. Refresh feeds to check for new articles. Read history remains available under All articles.":"Choose an unread article from the list.",blocks:[]),baseURL:home)
    }
    func openWeb(_ url:URL){if !browserID.isEmpty,let app=NSWorkspace.shared.urlForApplication(withBundleIdentifier:browserID){NSWorkspace.shared.open([url],withApplicationAt:app,configuration:NSWorkspace.OpenConfiguration()){[weak self] _,error in if let error=error{DispatchQueue.main.async{self?.alert("Browser could not open",error.localizedDescription)}}}}else{NSWorkspace.shared.open(url)}}
