    @objc func browserSettings(){let a=NSAlert();a.messageText="Browser & Email";a.informativeText="Article headings and webmail drafts open in the browser selected here. This does not change your Mac's default browser.";let stack=NSStackView();stack.orientation = .vertical;stack.alignment = .leading;stack.spacing=10;stack.frame=NSRect(x:0,y:0,width:340,height:120);let browser=NSPopUpButton(frame:NSRect(x:0,y:0,width:330,height:28));browser.addItem(withTitle:"Default web browser");let apps=NSWorkspace.shared.urlsForApplications(toOpen:URL(string:"https://example.com")!).sorted{$0.lastPathComponent<$1.lastPathComponent};for url in apps{browser.addItem(withTitle:FileManager.default.displayName(atPath:url.path))};if let i=apps.firstIndex(where:{Bundle(url:$0)?.bundleIdentifier==browserID}){browser.selectItem(at:i+1)};let mail=NSPopUpButton(frame:NSRect(x:0,y:0,width:330,height:28));mail.addItems(withTitles:ReaderLinks.services);mail.selectItem(withTitle:emailService);stack.addArrangedSubview(NSTextField(labelWithString:"Open webpages with:"));stack.addArrangedSubview(browser);stack.addArrangedSubview(NSTextField(labelWithString:"Preferred email service:"));stack.addArrangedSubview(mail);a.accessoryView=stack;a.addButton(withTitle:"Save");a.addButton(withTitle:"Cancel");if a.runModal() == .alertFirstButtonReturn{let i=browser.indexOfSelectedItem;browserID=i==0 ? "":Bundle(url:apps[i-1])?.bundleIdentifier ?? "";emailService=mail.titleOfSelectedItem ?? "Gmail";persist()}}
    @objc func openOriginal(){if let s=selected?["url"] as? String,let u=URL(string:s){openWeb(u)}}
    @objc func toggleSidebar(){split.arrangedSubviews[0].isHidden.toggle();split.adjustSubviews()}
    @objc func addFeed(){guard ready else{alert("Connect first","Wait for the local library to open, then add a public feed.");return};let a=NSAlert();a.messageText="Add public feed";a.informativeText="Paste an RSS/Atom URL, a website with feed discovery, or a public Substack.";let url=NSTextField(frame:NSRect(x:0,y:0,width:400,height:28));url.placeholderString="https://example.com/feed";a.accessoryView=url;a.addButton(withTitle:"Add");a.addButton(withTitle:"Cancel");guard a.runModal() == .alertFirstButtonReturn else{return};let raw=url.stringValue;status.stringValue="Finding feed…";js("feed",raw){[weak self] d,error in guard let self=self else{return};guard let d=d,let address=d["url"] as? String else{self.alert("Could not add feed",error ?? "No feed was found");return};if self.feeds.contains(where:{$0["url"] as? String==address}){self.alert("Already subscribed","This feed is already in your sidebar.");return};self.feeds.append(["name":d["title"] as? String ?? address,"url":address]);self.persist();self.sidebar.reloadData();self.refresh()}}
    @objc func removeFeed(){let row=sidebar.selectedRow;guard row>=4,row-4<feeds.count else{return};let a=NSAlert();a.messageText="Remove \(feeds[row-4]["name"] as? String ?? "feed")?";a.informativeText="Read Later articles are kept.";a.addButton(withTitle:"Remove");a.addButton(withTitle:"Cancel");if a.runModal() == .alertFirstButtonReturn{let f=feeds.remove(at:row-4);articles.removeAll{$0["feed"] as? String==f["url"] as? String};currentFilter="all";sidebar.reloadData();sidebar.selectRowIndexes(IndexSet(integer:0),byExtendingSelection:false);persist();rebuildList()}}
    @objc func importOPML(){guard ready else{return};let p=NSOpenPanel();p.canChooseDirectories=false;p.allowsMultipleSelection=false;p.beginSheetModal(for:window){[weak self] result in guard let self=self,result == .OK,let url=p.url else{return};do{let d=try Data(contentsOf:url);let imported=try ReaderOPML.decode(d);var count=0;for f in imported where self.feeds.count<250{if !self.feeds.contains(where:{$0["url"] as? String==f["url"] as? String}){self.feeds.append(f);count+=1}};self.persist();self.sidebar.reloadData();self.refresh();self.status.stringValue="Imported \(count) public feeds"}catch{self.alert("Import failed",error.localizedDescription)}}}
    @objc func exportOPML(){let p=NSSavePanel();p.nameFieldStringValue="Reader-subscriptions.opml";p.beginSheetModal(for:window){[weak self] result in guard let self=self,result == .OK,let url=p.url else{return};let xml=ReaderOPML.encode(self.feeds);do{try xml.write(to:url,atomically:true,encoding:.utf8)}catch{self.alert("Export failed",error.localizedDescription)}}}
    @objc func about(){alert("Reader — Working build","Native macOS feed navigation, article list, search and controls, with WebKit for article rendering. The working name and final logo will be decided after testing. Public article completeness and publisher availability vary.")}
    func alert(_ title:String,_ text:String){let a=NSAlert();a.messageText=title;a.informativeText=text;a.beginSheetModal(for:window)}
    func applicationShouldTerminateAfterLastWindowClosed(_ sender:NSApplication)->Bool{true}
    func webView(_ webView:WKWebView,decidePolicyFor action:WKNavigationAction,decisionHandler:@escaping(WKNavigationActionPolicy)->Void){guard let u=action.request.url else{decisionHandler(.cancel);return};if u.scheme=="mailto"{NSWorkspace.shared.open(u);decisionHandler(.cancel);return};if action.shouldPerformDownload{decisionHandler(.download);return};if webView !== bridge && action.navigationType == .linkActivated && u.host != home.host{openWeb(u);decisionHandler(.cancel);return};decisionHandler(.allow)}
    func webView(_ webView:WKWebView,createWebViewWith configuration:WKWebViewConfiguration,for action:WKNavigationAction,windowFeatures:WKWindowFeatures)->WKWebView?{let view=WKWebView(frame:.zero,configuration:configuration);view.uiDelegate=self;view.navigationDelegate=self;let w=NSWindow(contentRect:NSRect(x:0,y:0,width:600,height:760),styleMask:[.titled,.closable,.resizable],backing:.buffered,defer:false);w.title="Reader";w.contentView=view;w.center();w.makeKeyAndOrderFront(nil);popupWindows.append(w);return view}
    func webViewDidClose(_ webView:WKWebView){popupWindows.first(where:{$0.contentView === webView})?.close()}
    func webView(_ webView:WKWebView,runJavaScriptConfirmPanelWithMessage message:String,initiatedByFrame frame:WKFrameInfo,completionHandler:@escaping(Bool)->Void){let a=NSAlert();a.messageText=message;a.addButton(withTitle:"OK");a.addButton(withTitle:"Cancel");completionHandler(a.runModal() == .alertFirstButtonReturn)}
    func webView(_ webView:WKWebView,runOpenPanelWith parameters:WKOpenPanelParameters,initiatedByFrame frame:WKFrameInfo,completionHandler:@escaping([URL]?)->Void){let p=NSOpenPanel();p.canChooseDirectories=false;p.allowsMultipleSelection=parameters.allowsMultipleSelection;p.beginSheetModal(for:window){completionHandler($0 == .OK ? p.urls:nil)}}
    func webView(_ webView:WKWebView,navigationAction:WKNavigationAction,didBecome download:WKDownload){download.delegate=self}
    func download(_ download:WKDownload,decideDestinationUsing response:URLResponse,suggestedFilename:String,completionHandler:@escaping(URL?)->Void){let p=NSSavePanel();p.nameFieldStringValue=suggestedFilename;p.beginSheetModal(for:window){completionHandler($0 == .OK ? p.url:nil)}}
